class ContextLengthMetric(BaseMetric):
    def __init__(self, max_tokens: int = {{max_tokens}}, threshold: float = {{threshold}}):
        self.threshold = threshold
        self.max_tokens = max_tokens
        self.evaluation_model = "token-counter"

    def _count_tokens(self, text: str) -> int:
        return len(text) // 2

    def measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        contexts = test_case.retrieval_context or []
        total_tokens = sum(self._count_tokens(c) for c in contexts)
        if total_tokens > self.max_tokens:
            self.score = 0.0
            self.reason = f"检索上下文共 {total_tokens} tokens，超过上限 {self.max_tokens}"
        else:
            self.score = 1.0
            self.reason = f"检索上下文共 {total_tokens} tokens，未超上限 {self.max_tokens}"
        self.success = self.score >= self.threshold
        return self.score

    async def a_measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        return self.measure(test_case)

    def is_successful(self) -> bool:
        return bool(self.score and self.score >= self.threshold)

    @property
    def __name__(self):
        return "Context Length Check"
